import type { z } from "zod";
import type { concernSchema, proposalSchema, stateSchema, decisionSchema, signalSchema, reportResultSchema, dimensionsSchema, inputs } from "./schema";
export type Concern = z.infer<typeof concernSchema>;
export type Proposal = z.infer<typeof proposalSchema>;
export type State = z.infer<typeof stateSchema>;
export type Decision = z.infer<typeof decisionSchema>;
export type Signal = z.infer<typeof signalSchema>;
export type ReportResult = z.infer<typeof reportResultSchema>;
export type Dimensions = z.infer<typeof dimensionsSchema>;
export type Tool = keyof typeof inputs;
export type Caller = { kind: "module"; module: string; moduleId: string; hash: string } | { kind: "provider"; runId: string } | { kind: "owner"; via: string | null } | { kind: "kernel" };
export type Call = (target: string, args: Record<string, unknown>, options?: { key?: string; timeoutMs?: number }) => Promise<unknown>;
export type NoteInput = z.infer<typeof inputs.note>;
export type SignalInput = z.infer<typeof inputs.signal>;
